package com.example.starter.dispatch.domain;

/**
 * 调度令生命周期状态。
 */
public enum OrderStatus {

    /** 已下达，等待闸站签收。 */
    ISSUED,
    /** 已签收，正在逐门执行。 */
    ACKNOWLEDGED,
    /** 全部闸门回执收齐且终态判定完成（可能存在执行偏差告警）。 */
    COMPLETED,
    /** 超过执行时限未收齐回执，已超时升级并通知上级。 */
    TIMEOUT_ESCALATED,
    /** 签收前撤销，终态。 */
    CANCELLED,
    /** 签收后人工中止，终态，保留已执行闸门实际开度。 */
    ABORTED
}

package com.example.starter.dispatch.domain;

/**
 * 调度令中单个闸门执行项的状态。
 */
public enum GateStepStatus {

    /** 待执行：前序闸门尚未回执完成，本门不得启动。 */
    PENDING,
    /** 已收到闸站回执（到位或偏差以 inPosition 区分）。 */
    RECEIVED
}

package com.example.starter.dispatch.domain;

/**
 * 调度通知类型（对上级/外部监控系统的本地模拟留痕）。
 */
public enum NotificationType {

    /** 超时升级，立即通知上级。 */
    ESCALATION,
    /** 回执实际开度偏差超限，自动告警。 */
    DEVIATION_ALARM
}

