        } finally {
            pool.shutdownNow();
        }

        OrderView finalView = service.getOrder(requestId);
        assertThat(finalView.status())
                .as("超时与最后回执竞态后必须是 COMPLETED 或 TIMEOUT_ESCALATED 之一")
